-- Generated by `engine types sync` from types/*.toml (sqlite).
-- create type `article`; create type `author`; create type `settings`

CREATE TABLE content_article (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    slug TEXT NOT NULL UNIQUE CHECK (length(slug) BETWEEN 1 AND 80 AND slug NOT GLOB '*[^a-z0-9-]*' AND slug NOT GLOB '-*' AND slug NOT GLOB '*-' AND slug NOT GLOB '*--*'),
    status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'published')),
    version INTEGER NOT NULL DEFAULT 1,
    created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    published_at TEXT,
    "title" TEXT,
    "summary" TEXT,
    "body" TEXT,
    "author" INTEGER REFERENCES content_author (id) ON DELETE SET NULL,
    "sections" TEXT CHECK ("sections" IS NULL OR json_valid("sections"))
);
CREATE TRIGGER content_article_changes_insert AFTER INSERT ON content_article BEGIN
    INSERT INTO engine_changes (content_type, item_id, op) VALUES ('article', NEW.id, 'INSERT');
END;
CREATE TRIGGER content_article_changes_update AFTER UPDATE ON content_article BEGIN
    INSERT INTO engine_changes (content_type, item_id, op) VALUES ('article', NEW.id, 'UPDATE');
END;
CREATE TRIGGER content_article_changes_delete AFTER DELETE ON content_article BEGIN
    INSERT INTO engine_changes (content_type, item_id, op) VALUES ('article', OLD.id, 'DELETE');
END;

