    updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    published_at TEXT,
    "name" TEXT,
    "bio" TEXT,
    "website" TEXT
);
CREATE TRIGGER content_author_changes_insert AFTER INSERT ON content_author BEGIN
    INSERT INTO engine_changes (content_type, item_id, op) VALUES ('author', NEW.id, 'INSERT');
END;
CREATE TRIGGER content_author_changes_update AFTER UPDATE ON content_author BEGIN
    INSERT INTO engine_changes (content_type, item_id, op) VALUES ('author', NEW.id, 'UPDATE');
END;
CREATE TRIGGER content_author_changes_delete AFTER DELETE ON content_author BEGIN
