CREATE TABLE content_settings (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    slug TEXT NOT NULL UNIQUE CHECK (length(slug) BETWEEN 1 AND 80 AND slug NOT GLOB '*[^a-z0-9-]*' AND slug NOT GLOB '-*' AND slug NOT GLOB '*-' AND slug NOT GLOB '*--*'),
    status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'published')),
    version INTEGER NOT NULL DEFAULT 1,
    created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    published_at TEXT,
    "tagline" TEXT,
    "footer_note" TEXT
);
-- Singleton: at most one row.
CREATE TRIGGER content_settings_one BEFORE INSERT ON content_settings
    WHEN (SELECT count(*) FROM content_settings) > 0
    BEGIN SELECT RAISE(ABORT, 'settings is a singleton'); END;
CREATE TRIGGER content_settings_changes_insert AFTER INSERT ON content_settings BEGIN
    INSERT INTO engine_changes (content_type, item_id, op) VALUES ('settings', NEW.id, 'INSERT');
END;
CREATE TRIGGER content_settings_changes_update AFTER UPDATE ON content_settings BEGIN
    INSERT INTO engine_changes (content_type, item_id, op) VALUES ('settings', NEW.id, 'UPDATE');
END;
CREATE TRIGGER content_settings_changes_delete AFTER DELETE ON content_settings BEGIN
    INSERT INTO engine_changes (content_type, item_id, op) VALUES ('settings', OLD.id, 'DELETE');
END;
